from collections import Counter,deque
def comps(g,col,seen,cells):
    # flood fill starting from given cells
    comp=set(); dq=deque(cells)
    while dq:
        y,x=dq.popleft()
        if (y,x) in comp: continue
        comp.add((y,x))
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==col and (ny,nx) not in comp:
                dq.append((ny,nx))
    return comp
def analyze(g):
    cnt=Counter(x for r in g for x in r)
    res={}
    for col in sorted(cnt,key=str):
        cs=[]
        seen=set()
        for y in range(len(g)):
            for x in range(len(g[0])):
                if g[y][x]==col and (y,x) not in seen:
                    seen.add((y,x)); comp=comps(g,col,seen,{(y,x)})
                    cs.append(comp)
        res[col]=sorted([len(c) for c in cs])
    return cnt,res
