from collections import Counter
def comps_nbg(g):
    cnt=Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]
    H=len(g);W=len(g[0]);seen=[[False]*W for _ in range(H)];out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
                st=[(r,c)];seen[r][c]=True;cells=[];col=g[r][c]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True;st.append((x,y))
                out.append((sorted(cells),col))
    return bg,out
def nshape(comp):
    br=min(r for r,c in comp);bc=min(c for r,c in comp)
    return tuple(sorted((r-br,c-bc) for r,c in comp))
