        # decide: recolor members whose color is not the majority in this group, to majority color
        cnt=Counter(c for _,c in vv); top=cnt.most_common(1)[0][0]
        for comp,col in vv:
            if col!=top:
                for r,c in comp: out[r][c]=top
    return out
